# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift


def make_shift(worker, day, text):
    return Shift(worker, day, parse_span(text))


class TimesheetTests(unittest.TestCase):
    def test_counts_and_hours(self):
        lines = timesheet_lines(
            [
                make_shift("Ana", "mon", "09:00-13:30"),
                make_shift("Ana", "tue", "09:00-12:00"),
            ]
        )
        self.assertEqual(
            lines, ["Ana: 2 shifts, 7.5 hours"]
        )

    def test_busiest_first(self):
        lines = timesheet_lines(
            [
                make_shift("Ben", "mon", "09:00-11:00"),
                make_shift("Cleo", "mon", "09:00-17:00"),
                make_shift("Ana", "tue", "09:00-10:00"),
            ]
        )
        self.assertEqual(
            lines,
            [
                "Cleo: 1 shift, 8.0 hours",
                "Ben: 1 shift, 2.0 hours",
                "Ana: 1 shift, 1.0 hours",
            ],
        )

    def test_ties_go_by_name(self):
        lines = timesheet_lines(
            [
                make_shift("Ben", "mon", "09:00-11:00"),
                make_shift("Ana", "tue", "09:00-11:00"),
            ]
        )
        self.assertTrue(lines[0].startswith("Ana"))

    def test_rounds_to_one_decimal(self):
        lines = timesheet_lines(
            [make_shift("Ana", "mon", "09:00-09:20")]
        )
        self.assertEqual(lines, ["Ana: 1 shift, 0.3 hours"])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            with self.assertRaises(ValueError):
                item = make_shift(blank, "mon", "9:00-9:30")
                timesheet_lines([item])


if __name__ == "__main__":
    unittest.main()
